<?php
namespace App\RecipeProduction\Services;
use App\Models\Product;
use App\RecipeProduction\Models\{MaterialCategory,ProductionOrder,ProductionOrderItem,RawMaterial,Recipe,RecipeItem,StockMovement};
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
use RuntimeException;

class RecipeProductionService
{
    public function recalculateMaterial(array $data): array { $size=(float)$data['package_size']; if($size<=0) throw ValidationException::withMessages(['package_size'=>'Package size must be greater than zero.']); return array_merge($data,['unit_cost'=>round((float)$data['package_cost']/$size,6)]); }
    public function saveRecipe(array $data, ?Recipe $recipe=null): Recipe { return DB::transaction(function() use($data,$recipe){ $product=Product::query()->findOrFail($data['product_id']); $existing=Recipe::query()->where('product_id',$product->id)->when($recipe,fn($q)=>$q->whereKey('id','!=',$recipe->id))->exists(); if($existing) throw ValidationException::withMessages(['product_id'=>'This product already has a fixed recipe.']); $items=$data['items']; $materialIds=array_column($items,'material_id'); if(count($materialIds)!==count(array_unique($materialIds))) throw ValidationException::withMessages(['items'=>'The same raw material cannot be repeated.']); $recipe ??= new Recipe(); $recipe->fill(['product_id'=>$product->id,'code'=>$recipe->code ?: 'REC-'.str_pad((string)(Recipe::withTrashed()->max('id')+1),6,'0',STR_PAD_LEFT),'package_size'=>$data['package_size']??null,'package_unit'=>$data['package_unit']??null,'description'=>$data['description']??null,'status'=>$data['status']??'active']); $recipe->save(); $total=0; $recipe->items()->delete(); foreach($items as $item){$material=RawMaterial::query()->findOrFail($item['material_id']); $cost=round(((float)$item['required_quantity']+(float)($item['waste_quantity']??0))*(float)$material->unit_cost,6); $recipe->items()->create(['material_id'=>$material->id,'required_quantity'=>$item['required_quantity'],'unit'=>$item['unit']??$material->base_unit,'waste_quantity'=>$item['waste_quantity']??0,'unit_cost'=>$material->unit_cost,'total_cost'=>$cost]); $total += $cost;} $recipe->update(['total_cost'=>round($total,6)]); return $recipe->load(['product','items.material']); }); }
    public function confirm(ProductionOrder $order): ProductionOrder { return DB::transaction(function() use($order){ $order->load(['recipe.items.material','items']); if($order->status !== 'draft') throw new RuntimeException('Only draft orders can be confirmed.'); $factor=(float)$order->planned_quantity; $expected=0; foreach($order->recipe->items as $recipeItem){$qty=round((float)$recipeItem->required_quantity*$factor,6); $waste=round((float)$recipeItem->waste_quantity*$factor,6); $needed=$qty+$waste; $material=RawMaterial::query()->lockForUpdate()->findOrFail($recipeItem->material_id); if((float)$material->available_quantity < $needed) throw ValidationException::withMessages(['stock'=>"Insufficient stock for {$material->name}."]); $material->available_quantity=round((float)$material->available_quantity-$needed,6); $material->save(); $cost=round($needed*(float)$material->unit_cost,6); $order->items()->create(['material_id'=>$material->id,'expected_quantity'=>$qty,'expected_waste'=>$waste,'actual_quantity'=>$qty,'actual_waste'=>$waste,'unit_cost_snapshot'=>$material->unit_cost,'total_cost'=>$cost,'unit'=>$recipeItem->unit]); StockMovement::create(['material_id'=>$material->id,'production_order_id'=>$order->id,'type'=>'production_consumption','quantity_delta'=>-$needed,'balance_after'=>$material->available_quantity,'unit_cost'=>$material->unit_cost,'created_by'=>auth()->id()]); $expected += $cost;} $order->update(['status'=>'completed','produced_quantity'=>$order->planned_quantity,'expected_cost'=>$expected,'actual_cost'=>$expected,'actual_waste'=>$order->items()->sum('actual_waste'),'confirmed_at'=>now()]); if($order->product){$order->product->increment('stock',$order->produced_quantity);} return $order->fresh(['product','recipe','items.material']); }); }
}
